import{_ as l,r as e,o as c,c as i,e as t,a as s,s as r,d as a}from"./chunks/framework.CXcwiNg-.js";const q=JSON.parse('{"title":"邮件配置 - October CMS - 3.x","titleTemplate":false,"description":"了解如何设置邮件发送服务。","frontmatter":{"subtitle":"了解如何设置邮件发送服务。"},"headers":[{"level":2,"title":"驱动程序先决条件","slug":"驱动程序先决条件","link":"#驱动程序先决条件","children":[{"level":3,"title":"Mailgun 驱动程序","slug":"mailgun-驱动程序","link":"#mailgun-驱动程序","children":[]},{"level":3,"title":"Postmark 驱动程序","slug":"postmark-驱动程序","link":"#postmark-驱动程序","children":[]},{"level":3,"title":"SES 驱动程序","slug":"ses-驱动程序","link":"#ses-驱动程序","children":[]}]},{"level":2,"title":"邮件与本地开发","slug":"邮件与本地开发","link":"#邮件与本地开发","children":[{"level":3,"title":"Log 驱动程序","slug":"log-驱动程序","link":"#log-驱动程序","children":[]},{"level":3,"title":"通用收件人","slug":"通用收件人","link":"#通用收件人","children":[]},{"level":3,"title":"模拟邮件模式","slug":"模拟邮件模式","link":"#模拟邮件模式","children":[{"level":4,"title":"另请参阅","slug":"另请参阅","link":"#另请参阅","children":[]}]}]}],"relativePath":"3.x/zh-cn/setup/mail-config.md","filePath":"3.x/zh-cn/setup/mail-config.md"}'),g={name:"3.x/zh-cn/setup/mail-config.md"};function u(d,n,h,k,m,f){const o=e("pre-heading"),p=e("post-heading");return c(),i("div",null,[t(o),n[0]||(n[0]=s("h1",null,"邮件配置",-1)),t(p),n[1]||(n[1]=r(`<p>October CMS 提供了 SMTP、Mailgun、SparkPost、Amazon SES 和 <code>sendmail</code> 的驱动程序，让您可以通过本地或云端服务快速开始发送邮件。</p><p>配置邮件服务有两种方式，一种是通过管理面板的<strong>设置 → 邮件设置</strong>，另一种是更新默认配置值。在以下示例中，我们将更新基于文件的配置值。</p><div class="custom-block tip"><p>管理面板中的邮件设置界面将覆盖基于文件的配置所提供的设置。点击<strong>恢复默认</strong>按钮将把邮件设置更新为最新值。如果您未在此表单上点击<strong>保存</strong>，则设置将继续从配置文件中读取。</p></div><h2 id="驱动程序先决条件"><a href="#驱动程序先决条件" class="header-anchor">#</a> 驱动程序先决条件</h2><p>在大多数情况下，您可以使用 SMTP 驱动程序，它受到大多数邮件提供商的支持。不过，使用基于 API 的驱动程序通常是更简单、更快速的方式。</p><h3 id="mailgun-驱动程序"><a href="#mailgun-驱动程序" class="header-anchor">#</a> Mailgun 驱动程序</h3><p>要使用 Mailgun 驱动程序，请通过 Composer 安装 Symfony 的 Mailgun Mailer 传输组件。</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token function">composer</span> require symfony/mailgun-mailer symfony/http-client
</code></pre></div><p>接下来，将 <code>config/mail.php</code> 配置文件中的 <code>driver</code> 选项设置为 <code>mailgun</code>。然后，确认您的 <code>config/services.php</code> 配置文件包含以下选项：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;mailgun&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;domain&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;your-mailgun-domain&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;secret&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;your-mailgun-key&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;endpoint&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;api.mailgun.net&#39;</span><span class="token punctuation">,</span> <span class="token comment">// api.eu.mailgun.net for EU</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h3 id="postmark-驱动程序"><a href="#postmark-驱动程序" class="header-anchor">#</a> Postmark 驱动程序</h3><p>要使用 Postmark 驱动程序，请通过 Composer 安装 Symfony 的 Postmark Mailer 传输组件。</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token function">composer</span> require symfony/postmark-mailer symfony/http-client
</code></pre></div><p>接下来，将应用程序 <code>config/mail.php</code> 配置文件中的 <code>default</code> 选项设置为 postmark。配置好应用程序的默认邮件发送器后，确认您的 <code>config/services.php</code> 配置文件包含以下内容：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;postmark&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;token&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">env</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;POSTMARK_TOKEN&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h3 id="ses-驱动程序"><a href="#ses-驱动程序" class="header-anchor">#</a> SES 驱动程序</h3><p>要使用 Amazon SES 驱动程序，您必须先安装 Amazon AWS SDK for PHP。您可以通过 Composer 包管理器安装此库。</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token function">composer</span> require aws/aws-sdk-php
</code></pre></div><p>接下来，将 <code>config/mail.php</code> 配置文件中的 <code>driver</code> 选项设置为 <code>ses</code>。然后，确认您的 <code>config/services.php</code> 配置文件包含以下选项：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;ses&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;your-ses-key&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;secret&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;your-ses-secret&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;region&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;ses-region&#39;</span><span class="token punctuation">,</span>  <span class="token comment">// e.g. us-east-1</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h2 id="邮件与本地开发"><a href="#邮件与本地开发" class="header-anchor">#</a> 邮件与本地开发</h2><p>在开发需要发送电子邮件的应用程序时，您可能不希望实际将邮件发送到真实的电子邮件地址。有几种方法可以&quot;禁用&quot;电子邮件的实际发送。</p><h3 id="log-驱动程序"><a href="#log-驱动程序" class="header-anchor">#</a> Log 驱动程序</h3><p>一种方案是在本地开发时使用 <code>log</code> 邮件驱动程序。该驱动程序会将所有电子邮件消息写入日志文件以供检查。有关按环境配置应用程序的更多信息，请查看<a href="./../setup/configuration.html">配置文档</a>。</p><h3 id="通用收件人"><a href="#通用收件人" class="header-anchor">#</a> 通用收件人</h3><p>另一种方案是为框架发送的所有电子邮件设置一个通用收件人。这样，应用程序生成的所有邮件都将发送到指定的地址，而不是发送消息时实际指定的地址。这可以通过 <code>config/mail.php</code> 配置文件中的 <code>to</code> 选项来实现：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;to&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;address&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dev@example.tld&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Dev Example&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h3 id="模拟邮件模式"><a href="#模拟邮件模式" class="header-anchor">#</a> 模拟邮件模式</h3><p>您可以使用 <code>Mail::pretend</code> 方法动态禁用邮件发送。当邮件发送器处于模拟模式时，消息将被写入应用程序的日志文件，而不是发送给收件人。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">pretend</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="另请参阅"><a href="#另请参阅" class="header-anchor">#</a> 另请参阅</h4>`,31)),n[2]||(n[2]=s("div",{class:"custom-block also"},[s("ul",null,[s("li",null,[s("a",{href:"./../extend/system/sending-mail.html"},"发送邮件")]),s("li",null,[s("a",{href:"https://github.com/rainlab/sparkpost-plugin",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("SparkPost Plugin"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),s("span",{class:"sr-only"},"(opens new window)")])])])])],-1))])}const x=l(g,[["render",u]]);export{q as __pageData,x as default};
